<script setup>
import { computed, onMounted, ref } from 'vue'
import { Wheat } from 'lucide-vue-next'
import { loadLatestAnalysis } from '../services/analysisSession'
const area=ref(1), baselineYield=ref(450), vigorScore=ref(''), vigorLevel=ref(''), stage=ref(''), source=ref('未同步长势分析'), recordDate=ref('')
function deriveScore(result){
  const m=result?.growth_analysis?.metrics
  if(m){ const coverage=Number(m.vegetation_coverage?.fraction||0), green=Number(m.green_degree?.mean_green_channel_ratio||0), cv=Number(m.distribution_uniformity?.coefficient_of_variation ?? 1); return Math.max(0,Math.min(100,(coverage/.75*100)*.45+(green*100)*.35+((1-cv/1.5)*100)*.2)) }
  const vigor=result?.growth_analysis?.vigor_assessment
  if(vigor?.vigor_score != null) return Number(vigor.vigor_score)
  if(result?.vigor_score != null) return Number(result.vigor_score)
  return null
}

onMounted(async()=>{ const saved=loadLatestAnalysis(); if(saved?.result){ vigorScore.value=deriveScore(saved.result) ?? ''; vigorLevel.value=saved.result?.vigor_level || saved.result?.growth_analysis?.vigor_assessment?.vigor_level || ''; stage.value=saved.stageResult?.predicted_stage_name || saved.result.growth_stage?.predicted_stage_name || ''; recordDate.value=saved.result.completed_at_utc || saved.result.created_at_utc || ''; source.value='已同步最近一次长势分析结果' } if(vigorScore.value===''){try{const response=await fetch('/api/growth/history');if(response.ok){const data=await response.json();const latest=(data.items||[]).sort((a,b)=>String(b.completed_at_utc||'').localeCompare(String(a.completed_at_utc||'')))[0];if(latest){vigorScore.value=deriveScore(latest) ?? latest.vigor_score ?? '';vigorLevel.value=latest.vigor_level || '';stage.value=stage.value||latest.growth_stage?.predicted_stage_name||'';recordDate.value=latest.completed_at_utc||'';source.value='已同步最近一次真实长势分析记录'}}}catch{}}})
if (!vigorLevel.value && vigorScore.value !== '') vigorLevel.value = Number(vigorScore.value) >= 80 ? '长势较好' : (Number(vigorScore.value) >= 60 ? '长势一般' : '长势较弱')
const factor=computed(()=>{const score=Number(vigorScore.value);return Number.isFinite(score)&&score>0?Math.max(.7,Math.min(1.1,.55+score/100*.55)):1})
const normalYield=computed(()=>Number(baselineYield.value||0)*factor.value)
const lowYield=computed(()=>normalYield.value*.85)
const highYield=computed(()=>normalYield.value*1.1)
const totalNormal=computed(()=>Number(area.value||0)*normalYield.value/1000)
const totalLow=computed(()=>Number(area.value||0)*lowYield.value/1000)
const totalHigh=computed(()=>Number(area.value||0)*highYield.value/1000)
</script><template><div class="yield-page p3-layout"><header class="module-title"><div class="module-heading"><span class="module-icon"><Wheat :size="25" /></span><div><p class="module-eyebrow">FIELD YIELD OUTLOOK</p><h1>产量预测</h1><p>根据当前长势表观状态，估算小麦可能产量。</p></div></div><span class="module-status"><span></span>规则估算 · 当前状态</span></header><section class="yield-record-panel"><div class="record-cell"><span>综合评分</span><strong>{{ vigorScore === '' ? '待同步' : Number(vigorScore).toFixed(1) }}</strong></div><div class="record-cell"><span>当前生育期</span><strong>{{ stage || '待识别' }}</strong></div><div class="record-cell"><span>观测日期</span><strong>{{ recordDate || '未提供' }}</strong></div><small>{{ source }}；当前评分来自长势分析，不代表经过田间验证的亩产模型。</small></section><section class="yield-panel"><div class="yield-panel-title"><span>产量估算条件</span><small>只关注产量，不包含价格和收益</small></div><div class="yield-form yield-input-form"><label>种植面积（亩）<input v-model.number="area" type="number" min="0" /></label><label>当地基准亩产（kg/亩）<input v-model.number="baselineYield" type="number" min="0" /></label><label>当前综合评分<input :value="vigorScore === '' ? '请先完成长势分析' : Number(vigorScore).toFixed(1)" readonly /></label></div><p class="note">系统根据当前综合评分对基准亩产进行规则修正，结果为探索性估算，不是实测产量。</p></section><section class="yield-summary-grid"><article class="yield-summary-card"><span>低位估算</span><strong>{{ totalLow.toFixed(2) }} 吨</strong><small>{{ lowYield.toFixed(0) }} kg/亩</small></article><article class="yield-summary-card"><span>正常估算</span><strong>{{ totalNormal.toFixed(2) }} 吨</strong><small>{{ normalYield.toFixed(0) }} kg/亩</small></article><article class="yield-summary-card"><span>高位估算</span><strong>{{ totalHigh.toFixed(2) }} 吨</strong><small>{{ highYield.toFixed(0) }} kg/亩</small></article></section><section class="yield-visual-panel"><div class="yield-panel-title"><span>产量情景对比</span><small>基于面积与当前状态</small></div><div class="yield-bars"><div v-for="item in [{name:'低位',value:lowYield,color:'low'},{name:'正常',value:normalYield,color:'normal'},{name:'高位',value:highYield,color:'high'}]" :key="item.name" class="yield-bar-row"><span>{{ item.name }}</span><div><i :class="item.color" :style="{ width: `${Math.max(8, Math.min(100, Number(item.value || 0) / Math.max(Number(highYield || 1), 1) * 100))}%` }"></i></div><b>{{ item.value.toFixed(0) }} kg/亩</b></div></div></section><section class="yield-panel yield-limit-panel"><span>说明</span><p>当前页面只估算产量。销售价格、成本、收入和利润请前往“市场与收益”页面计算。</p></section></div></template><style scoped>
